# We need to find x[0]...x[5] where each x[i] is an integer from 0 to 6
# and x[i] = count of i in the sequence.

# Let's use brute force search since the space is small (7^6 = 117649 possibilities)

def check_sequence(seq):
    for i in range(len(seq)):
        if seq.count(i) != seq[i]:
            return False
    return True

# Brute force
from itertools import product

