# Let's check known magic sequences for various lengths
def is_magic(seq):
    n = len(seq)
    for i in range(n):
        if seq.count(i) != seq[i]:
            return False
    return True

# Check n=4
from itertools import product
for n in range(1, 11):
    solutions = []
    for seq in product(range(n+1), repeat=n):
        if sum(seq) != n:
            continue
        if is_magic(seq):
            solutions.append(seq)
    print(f"n={n}: {len(solutions)} solutions: {solutions}")

# Let's use a smarter search with pruning
def find_magic(n):
    # We know sum = n
    # We can use recursion with pruning

    def backtrack(seq, remaining_sum, idx):
        if idx == n:
            if remaining_sum == 0 and all(seq.count(i) == seq[i] for i in range(n)):
                return [seq[:]]
            return []

        solutions = []
        # The value at position idx can be from 0 to min(remaining_sum, n)
        max_val = min(remaining_sum, n)
        for v in range(max_val + 1):
            seq.append(v)
            solutions.extend(backtrack(seq, remaining_sum - v, idx + 1))
            seq.pop()
        return solutions

    return backtrack([], n, 0)

for n in range(1, 11):
    sols = find_magic(n)
    print(f"n={n}: {len(sols)} solutions: {sols}")
